from PIL import Image
for f in ['wrist_002.png','wrist_010.png','wrist_011.png','wrist_012.png']:
    im=Image.open(f).convert('L'); w,h=im.size; px=im.load()
    seen=set(); 
    for y0 in range(320,h):
        for x0 in range(w):
            if px[x0,y0]<90 and (x0,y0) not in seen:
                st=[(x0,y0)]; comp=[]
                seen.add((x0,y0))
                while st:
                    x,y=st.pop(); comp.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<w and 320<=ny<h and (nx,ny) not in seen and px[nx,ny]<90:
                            seen.add((nx,ny)); st.append((nx,ny))
                if len(comp)>30:
                    xs=[c[0] for c in comp]; ys=[c[1] for c in comp]
                    print(f,len(comp),round(sum(xs)/len(xs),1),round(sum(ys)/len(ys),1),min(xs),max(xs),min(ys),max(ys))
"

